#!/usr/bin/env node
/**
 * Generates the committed Semaphore v4 fixture used by test/integration/RealSemaphore.t.sol.
 *
 * The Foundry test cannot generate zero-knowledge proofs, so this script builds a deterministic group of
 * beneficiary identities and a real Groth16 proof per member, all scoped to delivery id 1 and signing the
 * message keccak256("AID_RECEIVED"). The test adds the same commitments in the same order, which reproduces
 * the same Merkle root on-chain, and then submits these proofs through DeliveryManager.confirmReceipt.
 *
 * Proving artifacts are downloaded once from the official Semaphore artifact host (snark-artifacts.pse.dev)
 * by @zk-kit/artifacts and cached in the OS temp directory.
 *
 *   pnpm --filter @poa/contracts fixture:semaphore
 */
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { Group } from '@semaphore-protocol/group'
import { Identity } from '@semaphore-protocol/identity'
import { generateProof, verifyProof } from '@semaphore-protocol/proof'
import { keccak256, toUtf8Bytes } from 'ethers'

const MEMBER_COUNT = 5
const SCOPE = 1n // delivery id 1 — the first delivery opened in the test
const SEED = process.env.SEMAPHORE_FIXTURE_SEED ?? 'proof-of-aid-fixture'
const MESSAGE = BigInt(keccak256(toUtf8Bytes('AID_RECEIVED')))

const hex = (value) => `0x${BigInt(value).toString(16).padStart(64, '0')}`

const identities = Array.from({ length: MEMBER_COUNT }, (_, i) => new Identity(`${SEED}:member:${i}`))
const group = new Group(identities.map((identity) => identity.commitment))

console.log(`group of ${MEMBER_COUNT} members, depth ${group.depth}, root ${group.root}`)

const proofs = []
for (const [index, identity] of identities.entries()) {
  const proof = await generateProof(identity, group, MESSAGE, SCOPE)
  if (!(await verifyProof(proof))) throw new Error(`proof ${index} failed local verification`)
  if (BigInt(proof.merkleTreeRoot) !== BigInt(group.root)) throw new Error(`proof ${index} has a foreign root`)
  proofs.push({
    merkleTreeDepth: proof.merkleTreeDepth,
    nullifier: hex(proof.nullifier),
    points: proof.points.map(hex),
  })
  console.log(`proof ${index + 1}/${MEMBER_COUNT} ok (nullifier ${hex(proof.nullifier).slice(0, 12)}…)`)
}

// Merkle proof the NGO needs to remove the last member (right-to-erasure path in BeneficiaryGroups).
const removalIndex = MEMBER_COUNT - 1
const removalProof = group.generateMerkleProof(removalIndex)
const groupAfterRemoval = new Group(identities.map((identity) => identity.commitment))
groupAfterRemoval.removeMember(removalIndex)

const fixture = {
  _comment:
    'Generated by generate-semaphore-fixture.mjs. Real Semaphore v4 Groth16 proofs over a deterministic ' +
    'group. Demo/test material only — these identity secrets are derived from a public seed.',
  seed: SEED,
  memberCount: MEMBER_COUNT,
  scope: hex(SCOPE),
  message: hex(MESSAGE),
  merkleTreeDepth: group.depth,
  merkleTreeRoot: hex(group.root),
  commitments: identities.map((identity) => hex(identity.commitment)),
  removal: {
    index: removalIndex,
    commitment: hex(identities[removalIndex].commitment),
    siblings: removalProof.siblings.map(hex),
    rootAfterRemoval: hex(groupAfterRemoval.root),
  },
  proofs,
}

const outPath = join(dirname(fileURLToPath(import.meta.url)), 'semaphore-proofs.json')
writeFileSync(outPath, `${JSON.stringify(fixture, null, 2)}\n`)
console.log(`\nwrote ${outPath}`)
